                diff0 += 1
            if int(S[i]) != cur1:
                diff1 += 1

            # 若未到末尾，根据 P[i] 更新下一位的目标字符
            if i < n - 1:
                v = int(P[i])
                cur0 ^= v
                cur1 ^= v

        print(min(diff0, diff1))

if __name__ == "__main__":
    solve()
